<script setup lang="ts">
import { reactive } from 'vue'
const props = defineProps<{ advisers: string[] }>()
const levelOptions = ['Grade 7', 'Grade 8', 'Grade 9', 'Grade 10', 'Grade 11', 'Grade 12', 'Others']
const form = reactive({ name: '', adviser: 'N/A', gradeLevel: 'Others' })
const emit = defineEmits<{ (event: 'close'): void; (event: 'save', value: typeof form): void }>()
function save() { if (form.name.trim()) emit('save', { ...form }) }
</script>
<template><div class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-4" @click.self="emit('close')"><form class="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl" @submit.prevent="save"><div class="flex justify-between"><h2 class="text-xl font-bold">Add Department</h2><button type="button" class="text-2xl text-slate-400" aria-label="Close" @click="emit('close')">&times;</button></div><div class="mt-5 space-y-3"><div><label for="department-name" class="mb-1 block text-sm font-medium text-slate-700">Department name</label><input id="department-name" v-model="form.name" required autofocus placeholder="e.g. Practicum" class="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" /></div><div><label for="department-level" class="mb-1 block text-sm font-medium text-slate-700">Grade level</label><select id="department-level" v-model="form.gradeLevel" class="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"><option v-for="level in levelOptions" :key="level" :value="level">{{ level }}</option></select></div><div><label for="department-adviser" class="mb-1 block text-sm font-medium text-slate-700">Adviser</label><select id="department-adviser" v-model="form.adviser" class="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"><option v-for="adviser in props.advisers" :key="adviser" :value="adviser">{{ adviser }}</option></select></div></div><div class="mt-6 flex justify-end gap-3"><button type="button" class="rounded-lg border px-4 py-2 text-sm" @click="emit('close')">Cancel</button><button class="rounded-lg bg-purple-600 px-4 py-2 text-sm font-semibold text-white">Add Department</button></div></form></div></template>